"""Tracing for interaction-event queue writes."""

from __future__ import annotations

import functools
from typing import Any, Callable, TypeVar, cast

from rasa.tracing.voice.shared import semconv
from rasa.tracing.voice.spans import add_event_to_current_span

_QueuePutMethod = TypeVar("_QueuePutMethod", bound=Callable[..., Any])


def traced_interaction_event_enqueue(
    put_method: _QueuePutMethod,
) -> _QueuePutMethod:
    """Trace an interaction event after it is successfully enqueued."""

    @functools.wraps(put_method)
    async def wrapper(self: Any, event: Any, *args: Any, **kwargs: Any) -> Any:
        result = await put_method(self, event, *args, **kwargs)
        add_event_to_current_span(
            semconv.EVENT_TURN_EVENT_ENQUEUED,
            {
                semconv.VOICE_TURN_EVENT_TYPE: type(event).__name__,
                semconv.VOICE_QUEUE_SIZE: self.size,
            },
        )
        return result

    return cast(_QueuePutMethod, wrapper)
